const list = document.getElementById('topDonations');
const root = document.documentElement;
let tickerSettings = { filterType: 'lifetime', currency: '₹' };
let widgetSettings = {};
let configText = '';

function filterDonations(items) {
  if (!Array.isArray(items)) return [];
  const now = new Date();
  let start = null;
  let end = null;
  if (tickerSettings.filterType === 'today') start = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  else if (tickerSettings.filterType === 'week') start = new Date(now.getTime() - 7 * 86400000);
  else if (tickerSettings.filterType === 'month') start = new Date(now.getTime() - 30 * 86400000);
  else if (tickerSettings.filterType === 'custom') {
    if (tickerSettings.customStart) start = new Date(tickerSettings.customStart);
    if (tickerSettings.customEnd) {
      end = new Date(tickerSettings.customEnd);
      end.setHours(23, 59, 59, 999);
    }
  }
  return items.filter(item => {
    const date = new Date(item.date);
    return (!start || date >= start) && (!end || date <= end);
  });
}

function renderTopFour(donations) {
  const ranked = filterDonations(donations)
    .filter(item => Number.isFinite(Number(item.tip)))
    .sort((a, b) => Number(b.tip) - Number(a.tip))
    .slice(0, 4);
  list.replaceChildren();
  list.style.setProperty('--entry-count', String(Math.max(ranked.length, 1)));
  if (!ranked.length) {
    const empty = document.createElement('div');
    empty.className = 'empty-state';
    empty.textContent = 'No donations in this period';
    list.appendChild(empty);
    return;
  }
  ranked.forEach((donation, index) => {
    const entry = document.createElement('div');
    entry.className = 'donation-entry';
    entry.dataset.rank = String(index + 1);
    const rank = document.createElement('span');
    rank.className = 'donation-rank';
    rank.textContent = `#${index + 1}`;
    const name = document.createElement('span');
    name.className = 'donation-name';
    name.textContent = donation.name || 'Anonymous';
    const amount = document.createElement('span');
    amount.className = 'donation-amount';
    amount.textContent = `: ${tickerSettings.currency || ''}${Number(donation.tip || 0).toLocaleString('en-IN')}`;
    entry.append(rank, name, amount);
    list.appendChild(entry);
    const baseSize = parseFloat(getComputedStyle(entry).fontSize);
    const availableWidth = entry.clientWidth;
    if (entry.scrollWidth > availableWidth && availableWidth > 0) {
      entry.style.fontSize = `${Math.max(10, baseSize * availableWidth / entry.scrollWidth * 0.96)}px`;
    }
  });
}

async function fetchConfig() {
  try {
    const response = await fetch('/config', { cache: 'no-store' });
    if (!response.ok) return;
    const text = await response.text();
    if (text === configText) return;
    configText = text;
    const allConfig = JSON.parse(text);
    tickerSettings = allConfig['donation-ticker'] || tickerSettings;
    widgetSettings = allConfig['top-donation'] || {};
    if (widgetSettings.accent) root.style.setProperty('--text-accent', widgetSettings.accent);
    if (widgetSettings.text) root.style.setProperty('--text-main', widgetSettings.text);
    if (widgetSettings.font) root.style.setProperty('--font-family', widgetSettings.font);
    if (widgetSettings.fontSize) root.style.setProperty('--font-size', `${widgetSettings.fontSize}rem`);
    fetchDonations();
  } catch (error) { console.error('Config fetch error', error); }
}

async function fetchDonations() {
  try {
    const response = await fetch(`/donations.json?_=${Date.now()}`, { cache: 'no-store' });
    if (response.ok) renderTopFour(await response.json());
  } catch (error) { console.error('Donation fetch error', error); }
}

fetchConfig();
fetchDonations();
setInterval(fetchConfig, 5000);
setInterval(fetchDonations, 3000);
